+import org.springframework.transaction.annotation.Transactional;
+
+@Service
+@RequiredArgsConstructor
+@Transactional
+public class SurfaceService {
+  private final SurfaceDao surfaces;
+  private final CourtDao courts;
+  private final MutationGuard guard;
+
+  public Surface getEntity(long id) {
+    return surfaces.find(id).orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "Surface not found"));
+  }
+  @Transactional(readOnly = true)
+  public SurfaceResponse get(long id) { return SurfaceResponse.from(getEntity(id)); }
+  @Transactional(readOnly = true)
+  public List<SurfaceResponse> list() { return surfaces.list().stream().map(SurfaceResponse::from).toList(); }
+  public SurfaceResponse create(Map<String, Object> input) {
+    guard.lock();
+    Surface surface = new Surface();
+    updateValues(surface, input, false);
+    surfaces.persist(surface);
+    return SurfaceResponse.from(surface);
+  }
+  public SurfaceResponse update(long id, Map<String, Object> input, boolean partial) {
+    guard.lock();
+    Surface surface = getEntity(id);
+    updateValues(surface, input, partial);
+    return SurfaceResponse.from(surface);
+  }
+  private void updateValues(Surface surface, Map<String, Object> input, boolean partial) {
+    Input.fields(input, Set.of("name", "pricePerMinute"), partial);
