+    BigDecimal price = input.containsKey("pricePerMinute") ? Input.price(input.get("pricePerMinute")) : surface.getPricePerMinute();
+    String key = name.toLowerCase(Locale.ROOT);
+    if (surfaces.exists(key, surface.getId())) throw new ApiException(HttpStatus.CONFLICT, "Surface name already exists");
+    surface.update(name, key, price);
+  }
+  public void delete(long id) {
+    guard.lock();
+    Surface surface = getEntity(id);
+    if (courts.assigned(id)) throw new ApiException(HttpStatus.CONFLICT, "Surface is assigned to a court");
+    surface.softDelete();
+  }
+}

